      "type": "object",
      "properties": {
        "pack": {
          "type": "string",
          "maxLength": 64,
          "pattern": "^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)*$",
          "not": {
            "const": "app"
          }
        },
        "required": {
          "type": "boolean"
        },
        "delivery": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9-]{0,31}$"
        }
      },
